function talentMilestones():ReadonlySet<TalentMilestone>{const result=new Set<TalentMilestone>();if(midgame.van.owned||workforceV3.fleet.some(v=>v.type==='van'))result.add('van');if(workforceV3.workers.length||midgame.worker.hired)result.add('first_worker');if(packB.hangarOwned)result.add('hangar');if(packC.salvageYardOwned)result.add('salvage_yard');if(packD.industrialWorkshopOwned)result.add('industrial_workshop');return result}
const currentBusinessStage=():BusinessStageId=>deriveBusinessStage({installedMachineCount:installed.size,vanOwned:midgame.van.owned||workforceV3.fleet.some(v=>v.type==='van'),firstWorkerHired:workforceV3.workers.length>0,hangarOwned:packB.hangarOwned,salvageYardOwned:packC.salvageYardOwned,industrialWorkshopOwned:packD.industrialWorkshopOwned,processingPlantOwned:packE.processingPlantOwned});
function ensureLegacyWorkerV3(index:number){const existing=workforceV3.workers[index];if(existing)return existing;const worker=hireWorkerV3(workforceV3,currentBusinessStage(),Date.now());if(worker)worker.name=`Рабочий ${index+1}`;return worker}
function ensureVehicleV3(type:VehicleTypeV3){let vehicle=workforceV3.fleet.find(v=>v.type===type&&!v.routeId);if(vehicle)return vehicle;return acquireVehicleV3(workforceV3,currentBusinessStage(),type,Date.now())}
function assignLegacyWorkerV3(index:number,zone:ZoneId){const worker=ensureLegacyWorkerV3(index);if(!worker)return;let vehicleId:string|null=null;if(index===0&&midgame.economyV2.vanWorker==='w1')vehicleId=workforceV3.fleet.find(v=>v.type==='van')?.id??null;createOrAssignRouteV3(workforceV3,{workerId:worker.id,zone,vehicleId,now:Date.now()})}
function workforceContext(now:number,offline:boolean){const e=effects();return{stage:currentBusinessStage(),now,offline,offlineCapHours:e.offlineCapHours,workerOutputMultiplier:e.workerOutputMultiplier*(offline?e.offlineEfficiency:1),workerShiftMultiplier:e.workerShiftMultiplier,benchmarks:midgame.economyV2.benchmarks}}
function applyWorkforceTick(now=Date.now(),offline=false){const result=simulateWorkforceV3(workforceV3,workforceContext(now,offline));for(const key of ['metal','copper','plastic'] as ResourceKind[])storage[key]+=result.total[key];return result}
function hireGenericWorker(){
  const stage=currentBusinessStage(),before=workforceV3.workers.length,cost=nextWorkerHireCost(workforceV3);
  if(before===0&&!zoneMastered(midgame,'z1')){showToast('Сначала полностью освой Зону 1');return null}
  const limit=workerCapacityForStage(stage);if(before>=limit){showToast(`На текущей базе нет свободных мест для персонала: ${before}/${limit}`);return null}
  if(cash<cost){showToast(`На найм нужно ${money(cost)} · не хватает ${money(cost-cash)}`);return null}
  const worker=hireWorkerV3(workforceV3,stage,Date.now());if(!worker)return null;cash-=cost;
  if(before===0){midgame.worker.hired=true;midgame.worker.lastTick=Date.now()}
  else if(before===1){packB.secondWorker.hired=true;packB.secondWorker.lastTick=Date.now()}
  else if(before===2){packC.crew3.hired=true;packC.crew3.role='scavenger';packC.crew3.lastTick=Date.now()}
  else if(before===3){packD.crew4.hired=true;packD.crew4.role='scavenger';packD.crew4.lastTick=Date.now()}
  showToast(`${worker.name} нанят · ${money(cost)}`);saveGame();renderGarage();return worker
}
function acquireGenericVehicle(type:VehicleTypeV3){const stage=currentBusinessStage();if(workforceV3.fleet.length>=fleetCapacityForStage(stage))return null;const costs={van:90_000,truck:260_000,recovery_rig:480_000} as const,cost=costs[type];if(cash<cost)return null;const vehicle=acquireVehicleV3(workforceV3,stage,type,Date.now());if(!vehicle)return null;cash-=cost;saveGame();renderGarage();return vehicle}
function sellGenericVehicle(vehicleId:string){const sale=sellVehicleV3(workforceV3,vehicleId);if(!sale)return null;cash+=sale.refund;showToast(`${sale.vehicle.name} продан · +${money(sale.refund)}`);saveGame();renderGarage();return sale}
function assignGenericRoute(workerId:string,zone:ZoneId,vehicleId:string|null=null){if(!zoneMastered(midgame,zone))return null;const route=createOrAssignRouteV3(workforceV3,{workerId,zone,vehicleId,now:Date.now()});if(route){saveGame();renderGarage()}return route}
function unassignGenericRoute(routeId:string){if(unassignRouteV3(workforceV3,routeId)){saveGame();renderGarage();return true}return false}
function trainGenericWorker(workerId:string){
  const worker=workforceV3.workers.find(w=>w.id===workerId);if(!worker)return false;
  if(worker.rank>=5){showToast(`${worker.name}: максимальный ранг`);return false}
  const cost=15_000*worker.rank;if(cash<cost){showToast(`Обучение стоит ${money(cost)} · не хватает ${money(cost-cash)}`);return false}
  cash-=cost;if(!trainWorkerV3(workforceV3,workerId)){cash+=cost;return false}
  showToast(`${worker.name}: ранг ${worker.rank} · обучение ${money(cost)}`);saveGame();renderGarage();return true
}
function setGenericWorkerRole(workerId:string,role:'scavenger'|'operator'|'logistician'|'technician'){const ok=setWorkerRoleV3(workforceV3,workerId,role);if(ok){saveGame();renderGarage()}return ok}
function operatorFactor(cellId:string){const worker=workforceV3.workers.find(w=>w.status==='production'&&w.productionCellId===cellId&&w.role==='operator');if(!worker)return 1;return Math.max(.68,1/(1.18+.06*(worker.rank-1)))}
type GenericProductionCellId='heavy_cell'|'plant_lines'|ProductionCellIdV1;
function productionCellAvailable(cellId:GenericProductionCellId){return cellId==='heavy_cell'?packC.salvageYardOwned:cellId==='plant_lines'?packE.processingPlantOwned:packD.industrialWorkshopOwned}
function assignGenericProduction(workerId:string,cellId:GenericProductionCellId){if(!effects().operatorUnlocked)return false;const worker=workforceV3.workers.find(w=>w.id===workerId);if(!worker||!productionCellAvailable(cellId))return false;const occupied=workforceV3.workers.find(w=>w.id!==workerId&&w.status==='production'&&w.productionCellId===cellId);if(occupied){occupied.status='idle';occupied.productionCellId=null}if(worker.routeId)unassignRouteV3(workforceV3,worker.routeId);worker.role='operator';worker.status='production';worker.routeId=null;worker.productionCellId=cellId;saveGame();renderGarage();return true}
function getProductionV3View(){const cells:any[]=[];if(packC.salvageYardOwned){const worker=workforceV3.workers.find(w=>w.status==='production'&&w.productionCellId==='heavy_cell');cells.push({id:'heavy_cell',label:'Тяжёлая ячейка',operatorId:worker?.id??null,operatorName:worker?.name??null,speedFactor:operatorFactor('heavy_cell'),status:packC.production?packC.production.kind:'свободна',remainingSec:packC.production?Math.max(0,(packC.production.endsAt-Date.now())/1000):0})}if(packD.industrialWorkshopOwned){const stock=currentIndustrialStockV1(),now=Date.now();for(const id of ['refining','fabrication','heavy_assembly'] as ProductionCellIdV1[]){const projection=productionCellProjectionV1(productionCellsV1,id,stock,now),worker=workforceV3.workers.find(w=>w.status==='production'&&w.productionCellId===id);cells.push({id,label:projection.label,operatorId:worker?.role==='operator'?worker.id:null,operatorName:worker?.role==='operator'?worker.name:null,speedFactor:operatorFactor(id),status:projection.status==='running'?projection.selectedPlan.label:projection.status==='blocked'?'нет входов':'свободна',remainingSec:projection.remainingSec})}}if(packE.processingPlantOwned){const worker=workforceV3.workers.find(w=>w.status==='production'&&w.productionCellId==='plant_lines');const active=packE.production.filter(job=>job.endsAt>Date.now());cells.push({id:'plant_lines',label:'Линии Processing Plant',operatorId:worker?.id??null,operatorName:worker?.name??null,speedFactor:operatorFactor('plant_lines'),status:active.length?`работает линий: ${active.length}`:'свободны',remainingSec:active.length?Math.max(0,Math.min(...active.map(job=>job.endsAt))-Date.now())/1000:0})}return{unlocked:effects().operatorUnlocked,cells}}
function contractContext():ContractBoardContext{
  const capabilities=new Set<string>();
  if(installed.has('press'))capabilities.add('processed:briquette');
  if(installed.has('wire'))capabilities.add('processed:cleanCopper');
  if(installed.has('plastic'))capabilities.add('processed:granulate');
  midgame.discoveredComponents.forEach(k=>capabilities.add(`component:${k}`));
  midgame.discoveredMidComponents.forEach(k=>capabilities.add(`mid:${k}`));
  if(zoneMastered(midgame,'z3')&&installed.has('press'))capabilities.add('materialB:steelBlank');
  if(zoneMastered(midgame,'z4')){capabilities.add('materialB:aluminiumBillet');capabilities.add('moduleB:drive');capabilities.add('moduleB:control');capabilities.add('moduleB:structural')}
  packB.discoveredIndustrial.forEach(k=>capabilities.add(`industrialB:${k}`));
  if(zoneMastered(midgame,'z5'))capabilities.add('materialC:alloyBillet');
  if(packC.discoveredIndustrial.includes('industrialController'))capabilities.add('moduleC:hydraulicPower');
  if(packC.discoveredIndustrial.includes('heavyHydraulicCylinder'))capabilities.add('moduleC:heavyFrame');
  packC.discoveredIndustrial.forEach(k=>capabilities.add(`industrialC:${k}`));
  if(packE.processingPlantOwned)capabilities.add('base:processingPlant');
  return{level:level(),capabilities};
}
const hiredWorkerSlots=():WorkerSlotId[]=>{const slots:WorkerSlotId[]=[];if(midgame.worker.hired)slots.push('w1');if(packB.secondWorker.hired)slots.push('w2');if(packC.crew3.hired)slots.push('w3');if(packD.crew4.hired)slots.push('w4');return slots};
const playerVanAvailable=()=>midgame.van.owned&&!vanAssignedToWorker(midgame.economyV2);
function dispatchWorkers(){const now=Date.now(),slots=hiredWorkerSlots();if(slots.length)dispatchWorkerShifts(midgame.economyV2,slots,now);const hours=2*effects().workerShiftMultiplier;for(const route of workforceV3.routes){route.startedAt=now;route.shiftEndsAt=now+hours*3_600_000;route.deliveredKg=0}workforceV3.lastSimulatedAt=now;showToast(`Смена запущена: ${workforceV3.routes.length} маршрут. · до ${hours.toFixed(1)} ч`);saveGame();renderGarage()}
function toggleWorkerVan(){if(!midgame.van.owned||!midgame.worker.hired)return;setVanWorker(midgame.economyV2,midgame.economyV2.vanWorker==='w1'?null:'w1');const route=workforceV3.routes.find(r=>r.workerIds.includes(workforceV3.workers[0]?.id));if(route)assignLegacyWorkerV3(0,route.zone);showToast(midgame.economyV2.vanWorker==='w1'?'Фургон назначен на маршрут рабочего':'Фургон возвращён игроку');saveGame();renderGarage();hud()}
