function applyPackDInventory(inv:PackDInventory){cash=inv.cash;storage.metal=inv.metal;processed.cleanCopper=inv.cleanCopper;processed.granulate=inv.granulate;packB.materials.steelBlank=inv.steelBlank;packB.materials.aluminiumBillet=inv.aluminiumBillet;packC.materials.alloyBillet=inv.alloyBillet;packB.modules.drive=inv.drive;packB.modules.control=inv.control;packC.modules.hydraulicPower=inv.hydraulicPower;packC.modules.heavyFrame=inv.heavyFrame;packB.industrial.gearbox=inv.gearbox;packB.industrial.generator=inv.generator;packC.industrial.industrialController=inv.industrialController;packC.industrial.heavyHydraulicCylinder=inv.heavyHydraulicCylinder}
