function applyPackEInventory(inv:PackEInventory){cash=inv.cash;storage.metal=inv.metal;processed.cleanCopper=inv.cleanCopper;processed.granulate=inv.granulate;packB.materials.steelBlank=inv.steelBlank;packB.materials.aluminiumBillet=inv.aluminiumBillet;packC.materials.alloyScrap=inv.alloyScrap;packC.materials.alloyBillet=inv.alloyBillet;packB.modules.drive=inv.drive;packB.modules.control=inv.control;packC.modules.hydraulicPower=inv.hydraulicPower;packC.modules.heavyFrame=inv.heavyFrame;packC.industrial.industrialController=inv.industrialController;packC.industrial.heavyHydraulicCylinder=inv.heavyHydraulicCylinder}
function currentIndustrialStockV1():IndustrialStockV1{const stock=emptyIndustrialStockV1();Object.assign(stock,{alloyScrap:packC.materials.alloyScrap,reinforcedAlloy:packC.materials.alloyBillet,structuralProfile:packB.materials.steelBlank,cleanCopper:processed.cleanCopper,bearing:storedComps.bearing,motor:storedComps.motor,hydraulic:storedComps.hydraulic,electronics:storedComps.electronics,pump:midgame.midComponents.pump,gearbox:packB.industrial.gearbox,industrialController:packC.industrial.industrialController,heavyHydraulicCylinder:packC.industrial.heavyHydraulicCylinder,drive:packB.modules.drive,control:packB.modules.control,structural:packB.modules.structural,hydraulicPower:packC.modules.hydraulicPower,heavyFrame:packC.modules.heavyFrame});return stock}
function applyIndustrialStockV1(stock:IndustrialStockV1){packC.materials.alloyScrap=stock.alloyScrap;packC.materials.alloyBillet=stock.reinforcedAlloy;packB.materials.steelBlank=stock.structuralProfile;processed.cleanCopper=stock.cleanCopper;storedComps.bearing=stock.bearing;storedComps.motor=stock.motor;storedComps.hydraulic=stock.hydraulic;storedComps.electronics=stock.electronics;midgame.midComponents.pump=stock.pump;packB.industrial.gearbox=stock.gearbox;packC.industrial.industrialController=stock.industrialController;packC.industrial.heavyHydraulicCylinder=stock.heavyHydraulicCylinder;packB.modules.drive=stock.drive;packB.modules.control=stock.control;packB.modules.structural=stock.structural;packC.modules.hydraulicPower=stock.hydraulicPower;packC.modules.heavyFrame=stock.heavyFrame}
function productionStaffForCellV1(cellId:ProductionCellIdV1){const worker=workforceV3.workers.find(w=>w.status==='production'&&w.productionCellId===cellId);return worker?{workerId:worker.id,workerName:worker.name,role:worker.role as ProductionStaffRoleV1,rank:worker.rank}:{workerId:null,workerName:null,role:'none' as const,rank:0}}
function assignProductionCellWorkerV1(workerId:string,cellId:ProductionCellIdV1,role?:ProductionStaffRoleV1){if(!packD.industrialWorkshopOwned)return false;const worker=workforceV3.workers.find(w=>w.id===workerId);if(!worker)return false;if(role&&role!=='none'&&worker.role!==role)setWorkerRoleV3(workforceV3,worker.id,role);if(worker.routeId)unassignRouteV3(workforceV3,worker.routeId);const occupied=workforceV3.workers.find(w=>w.id!==workerId&&w.status==='production'&&w.productionCellId===cellId);if(occupied){occupied.status='idle';occupied.productionCellId=null}worker.status='production';worker.routeId=null;worker.productionCellId=cellId;saveGame();renderGarage();return true}
function setProductionCellPlanRuntimeV1(cellId:ProductionCellIdV1,planId:ProductionPlanIdV1){if(!packD.industrialWorkshopOwned)return false;const ok=setProductionPlanV1(productionCellsV1,cellId,planId);if(ok){saveGame();renderGarage()}return ok}
function productionHeavySupportV1(){const rig=workforceV3.fleet.find(v=>v.type==='recovery_rig'&&!v.routeId);return rig?{kind:'recovery_rig' as const,vehicleId:rig.id,vehicleName:rig.name,durationFactor:.85}:{kind:'none' as const,vehicleId:null,vehicleName:null,durationFactor:1}}
function startProductionCellRuntimeV1(cellId:ProductionCellIdV1){if(!packD.industrialWorkshopOwned)return{ok:false,reason:'locked'};const stock=currentIndustrialStockV1(),support=cellId==='heavy_assembly'?productionHeavySupportV1():undefined,result=startProductionCellV1(productionCellsV1,cellId,stock,productionStaffForCellV1(cellId),Date.now(),support);if(result.ok){applyIndustrialStockV1(stock);saveGame();renderGarage()}return result}
function advanceProductionCellsRuntimeV1(now=Date.now()){const stock=currentIndustrialStockV1(),completed=advanceProductionCellsV1(productionCellsV1,stock,now);if(completed.length)applyIndustrialStockV1(stock);return completed}
function getProductionCellsV1View(){const stock=currentIndustrialStockV1(),now=Date.now();return{unlocked:packD.industrialWorkshopOwned,stock,heavySupport:productionHeavySupportV1(),cells:(['refining','fabrication','heavy_assembly'] as ProductionCellIdV1[]).map(id=>({...productionCellProjectionV1(productionCellsV1,id,stock,now),assignedWorker:productionStaffForCellV1(id)}))}}

const processingPlantContext=()=>({z8Mastered:zoneMastered(midgame,'z8'),industrialWorkshopOwned:packD.industrialWorkshopOwned,recoveryRigOwned:packD.recoveryRig.owned,staffingReady:workforceV3.workers.length>=3&&effects().operatorUnlocked});
function advancePlant(now=Date.now()){const output={value:packC.materials.alloyBillet},completed=advancePlantProduction(packE,output,now);packC.materials.alloyBillet=output.value;return completed}
function zoneGate(id:ZoneId){if(id==='z8')return canUnlockZ8({level:level(),z7Mastered:zoneMastered(midgame,'z7'),industrialWorkshopOwned:packD.industrialWorkshopOwned,recoveryRigOwned:packD.recoveryRig.owned});if(id==='z7')return canUnlockZ7({z6Mastered:zoneMastered(midgame,'z6'),salvageYardOwned:packC.salvageYardOwned,truckOwned:packB.truck.owned});if(id==='z5'||id==='z6')return canUnlockPackCZone(id,{z4Mastered:zoneMastered(midgame,'z4'),z5Mastered:zoneMastered(midgame,'z5'),hangarOwned:packB.hangarOwned,truckOwned:packB.truck.owned,controllerDiscovered:packC.discoveredIndustrial.includes('industrialController')});return zoneUnlock(midgame,id,zoneContext())}
const workshopSlots=()=>effects().workshopSlots+(packD.industrialWorkshopOwned?1:0);
const freeWorkshopSlots=()=>Math.max(0,workshopSlots()-activeWorkshopActions(workshop).length);
const jobForMachine=(id:MachineId,kind?:WorkshopJob['kind'])=>jobs.find(j=>j.machineId===id&&(!kind||j.kind===kind));

function saveGame(){const state:SaveStateV10={v:10,xp,storage:{...storage},components:{...storedComps},processed:{...processed},cash,installed:[...installed],machineLevels:{...machineLevels},talents:[...talents],equipmentLevels:{...equipmentLevels},scheduler:normalizeWorkshopScheduler(workshop),contract:{...contractState},totalDestroyed,lastSeen:Date.now(),midgame:normalizeMidgame(midgame),packB:normalizePackB(packB),packC:normalizePackC(packC),packD:normalizePackD(packD),packE:normalizePackE(packE),productionCellsV1:normalizeProductionCellsV1(productionCellsV1),workforceV3:normalizeWorkforceFleetV3(workforceV3)},raw=JSON.stringify(state),result=writeResilientSave(localStorage,SAVE_KEY,raw);if(!result.ok)diagnostics.record('save.write_failed','error',result.reason,{bytes:result.bytes})}
setInterval(saveGame,10000);addEventListener('beforeunload',saveGame);
function showToast(text:string){toastEl.textContent=text;toastEl.classList.add('show');toastUntil=2.2}
function gainXp(amount:number,pos?:Vec2){const before=level();xp+=amount;const after=level();if(pos)texts.push({x:pos.x,y:pos.y-48,text:formatXpGain(amount),color:'#9ce7ff',life:1.2});if(after>before)showToast(`Уровень ${after}! +1 очко мастерства`);renderProgress()}
function jobId(prefix:string){return `${prefix}-${Date.now()}-${Math.floor(Math.random()*1e6)}`}
function adjustedDuration(sec:number){return Math.max(5,sec/effects().workshopSpeedMultiplier)}
function consume(requirements:MachineRequirement[],multiplier=effects().machineCostMultiplier){for(const req of requirements){const need=requirementAmount(req,multiplier);if(req.kind==='cash')cash-=need;else if(req.kind==='resource')storage[req.key as ResourceKind]-=need;else storedComps[req.key as ComponentKind]-=need}}

function oneShotRequirements(action:WorkshopQueueAction):{requirements:MachineRequirement[];multiplier:number}|null{
  if(action.kind==='build_machine'&&action.machineId)return{requirements:MACHINE_DEFS[action.machineId].requirements,multiplier:effects().machineCostMultiplier};
  if(action.kind==='upgrade_machine'&&action.machineId&&action.targetLevel){const up=MACHINE_DEFS[action.machineId].upgrades.find(x=>x.toLevel===action.targetLevel);return up?{requirements:up.requirements,multiplier:effects().machineCostMultiplier}:null}
  if(action.kind==='equipment'&&action.equipmentId&&action.targetLevel){const up=EQUIPMENT_DEFS[action.equipmentId].upgrades.find(x=>x.toLevel===action.targetLevel);return up?{requirements:up.requirements,multiplier:1}:null}
  return null
}
function workshopAdapter(completed:string[]):WorkshopSchedulerAdapter{return{
  canStart(action){
    if(action.machineId&&activeWorkshopActions(workshop).some(other=>other.id!==action.id&&other.machineId===action.machineId))return{ok:false,reason:'Станок занят другим действием'};
    if(action.kind==='process_batch'){const amount=action.inputAmount??0,kind=action.inputResource;if(!kind||amount<=0)return{ok:false,reason:'Некорректный рецепт'};return storage[kind]+1e-9>=amount?{ok:true}:{ok:false,reason:`Не хватает: ${resourceName[kind]}`}}
    if(action.kind==='industrial_batch')return{ok:false,reason:'Промышленная batch-очередь ещё не подключена'};
    const recipe=oneShotRequirements(action);if(!recipe)return{ok:false,reason:'Рецепт больше недоступен'};return canAfford(recipe.requirements,inventory(),recipe.multiplier)?{ok:true}:{ok:false,reason:'Не хватает ресурсов'}
  },
  commit(action){if(action.kind==='process_batch'&&action.inputResource)storage[action.inputResource]-=action.inputAmount??0;else{const recipe=oneShotRequirements(action);if(recipe)consume(recipe.requirements,recipe.multiplier)}},
  complete(action){
    if(action.kind==='build_machine'&&action.machineId){installed.add(action.machineId);machineLevels[action.machineId]=1;completed.push(`✓ ${MACHINE_DEFS[action.machineId].name} установлен`)}
    else if(action.kind==='upgrade_machine'&&action.machineId&&action.targetLevel){machineLevels[action.machineId]=action.targetLevel;completed.push(`✓ ${MACHINE_DEFS[action.machineId].name}: ур. ${action.targetLevel}`)}
    else if(action.kind==='equipment'&&action.equipmentId&&action.targetLevel){equipmentLevels[action.equipmentId]=action.targetLevel;completed.push(`✓ ${EQUIPMENT_DEFS[action.equipmentId].name}: ур. ${action.targetLevel}`)}
    else if(action.kind==='process_batch'&&action.processKind){processed[action.processKind]+=action.outputAmount??0;completed.push(`✓ ${processedName[action.processKind]} +${(action.outputAmount??0).toFixed(1)} кг`);if(effects().autoFeed&&action.requestedCount===1&&action.machineId&&action.current)enqueueProcess(action.machineId,action.current.endsAt,true,1,false)}
  }
}}
function queueAndKick(action:WorkshopQueueAction,toast:string){if(!enqueueWorkshopAction(workshop,action))return false;advanceWorkshop(Date.now(),false);showToast(toast);saveGame();renderGarage();return true}
function enqueueBuild(id:MachineId){const def=MACHINE_DEFS[id];if(installed.has(id)||jobForMachine(id,'build_machine')||!machineUnlocked(def,context())||!canAfford(def.requirements,inventory(),effects().machineCostMultiplier))return;const now=Date.now(),duration=adjustedDuration(buildDurationSec(id));queueAndKick(createOneShotAction({id:jobId('build'),kind:'build_machine',label:`Сборка: ${def.name}`,machineId:id,targetLevel:1,createdAt:now,durationMs:duration*1000}),`${def.name} поставлен в очередь · ${fmtLong(duration)}`)}
function enqueueMachineUpgrade(id:MachineId){const def=MACHINE_DEFS[id],current=machineLevels[id]??1,up=nextUpgrade(def,current);if(!up||jobForMachine(id,'upgrade_machine')||unmetUnlocks(up.unlocks,context()).length||!canAfford(up.requirements,inventory(),effects().machineCostMultiplier))return;const now=Date.now(),duration=adjustedDuration(upgradeDurationSec(id,up.toLevel));queueAndKick(createOneShotAction({id:jobId('upgrade'),kind:'upgrade_machine',label:`${def.name} → ур. ${up.toLevel}`,machineId:id,targetLevel:up.toLevel,createdAt:now,durationMs:duration*1000}),`Прокачка поставлена в очередь · ${fmtLong(duration)}`)}
function enqueueEquipment(id:EquipmentId){const current=equipmentLevels[id],up=nextEquipmentUpgrade(id,current);if(!up||jobs.some(j=>j.kind==='equipment'&&j.equipmentId===id)||level()<up.minPlayerLevel||!canAfford(up.requirements,inventory(),1))return;const now=Date.now(),duration=adjustedDuration(up.durationSec);queueAndKick(createOneShotAction({id:jobId('equipment'),kind:'equipment',label:`${EQUIPMENT_DEFS[id].name}: ${up.name}`,equipmentId:id,targetLevel:up.toLevel,createdAt:now,durationMs:duration*1000}),`${up.name} поставлен в очередь · ${fmtLong(duration)}`)}
function enqueueProcess(id:MachineId,startAt=Date.now(),auto=false,requestedCount=1,kick=true){if(!installed.has(id)||id==='workbench')return false;const spec=processSpec(id,machineLevels[id]??1,effects().workshopYieldMultiplier);if(!spec||storage[spec.resource]+1e-9<spec.input)return false;const duration=adjustedDuration(spec.durationSec),action=createBatchAction({id:jobId(auto?'auto':'process'),label:spec.label,recipeId:`${id}:${spec.kind}`,machineId:id,processKind:spec.kind,inputResource:spec.resource,inputAmount:spec.input,outputAmount:spec.input*effects().workshopYieldMultiplier,durationMs:duration*1000,requestedCount,createdAt:startAt});if(!enqueueWorkshopAction(workshop,action))return false;if(kick){advanceWorkshop(Date.now(),false);if(!auto)showToast(`${spec.label} в очереди · ${requestedCount}×`);saveGame();renderGarage()}else syncJobsView();return true}
function advanceWorkshop(now=Date.now(),notify=false){const completed:string[]=[];advanceWorkshopScheduler(workshop,now,workshopSlots(),workshopAdapter(completed));removeTerminalWorkshopActions(workshop);syncJobsView();if(completed.length){saveGame();if(notify)showToast(completed.at(-1)!)}return completed}

function applyWorkerEconomyGain(gain:{resources:Record<ResourceKind,number>;components:Record<ComponentKind,number>;weight:number}){(Object.keys(gain.resources) as ResourceKind[]).forEach(k=>storage[k]+=gain.resources[k]);(Object.keys(gain.components) as ComponentKind[]).forEach(k=>storedComps[k]+=gain.components[k])}
function applyOffline(){
  const now=Date.now(),completed=advanceWorkshop(now,false),elapsed=Math.max(0,(now-loadedLastSeen)/3600000),e=effects(),hours=Math.min(elapsed,e.offlineCapHours);
  let gain={metal:0,copper:0,plastic:0};
  if(elapsed>=.1667){gain={metal:420*e.offlineEfficiency*hours,copper:27*e.offlineEfficiency*hours,plastic:75*e.offlineEfficiency*hours};storage.metal+=gain.metal;storage.copper+=gain.copper;storage.plastic+=gain.plastic}
  const packCCompleted=advancePackCProduction(packC,now),productionCellsCompleted=advanceProductionCellsRuntimeV1(now),plantCompleted=advancePlant(now),workforce=applyWorkforceTick(now,true);
  const workerWeight=workforce.reports.reduce((sum,report)=>sum+report.gainedKg,0);
  if(completed.length||packCCompleted||productionCellsCompleted.length||plantCompleted||elapsed>=.1667||workerWeight>.01){
    const routeRows=workforce.reports.filter(r=>r.elapsedHours>.001).map(r=>`<li><b>${r.workerNames.join(', ')||'Без рабочего'}</b> · ${ZONE_DEFS[r.zone].name} · ${r.vehicleName??'без транспорта'}<br><span>${r.kgPerHour.toFixed(0)} кг/ч · +${r.gainedKg.toFixed(1)} кг · ${r.stopReason==='vehicle_full'?'остановка: заполнен транспорт':r.stopReason==='shift_ended'?'остановка: смена закончилась':r.stopReason==='no_worker'?'остановка: нет рабочего':'маршрут продолжает работу'}</span></li>`).join('');
    $('offlineLoot').innerHTML=`<p>${hours.toFixed(1)} ч офлайн · эффективность базы ${(e.offlineEfficiency*100).toFixed(0)}%</p><div><span>База: металл <b>+${gain.metal.toFixed(1)} кг</b></span><span>медь <b>+${gain.copper.toFixed(1)} кг</b></span><span>пластик <b>+${gain.plastic.toFixed(1)} кг</b></span></div>${routeRows?`<h3>Маршруты</h3><ul class="offlineRoutesV3">${routeRows}</ul>`:''}${productionCellsCompleted.length?`<h3>Industrial Workshop</h3><ul class="offlineProductionCellsV1">${productionCellsCompleted.map(x=>`<li>${x.label}</li>`).join('')}</ul>`:''}${plantCompleted?`<h3>Processing Plant</h3><p>+${plantCompleted} Alloy Billet</p>`:''}${completed.length?`<h3>Мастерская завершила</h3><ul>${completed.map(x=>`<li>${x}</li>`).join('')}</ul>`:''}`;offlineScreen.hidden=false
  }
  saveGame()
}

function refreshField(){trip++;rng=mulberry32(hashSeed(`${baseSeed}:${midgame.currentZone}:${trip}`));targets=generateField(`${baseSeed}:field:${midgame.currentZone}:${trip}`,FIELD_NODE_COUNT);applyZoneProfile(targets,midgame.currentZone,rng);fieldZone=midgame.currentZone;fieldInitialTargetCount=targets.length;respawnSerial=0;nextRespawnAt=0;drops=[];texts=[];sparks=[];decor=makeDecor(mulberry32(hashSeed(`${baseSeed}:decor:${midgame.currentZone}:${trip}`)),WORLD.width,WORLD.height,midgame.currentZone);player.x=START_POS.x;player.y=START_POS.y;player.fx=1;player.fy=0;seedEl.textContent=`генерация ${baseSeed} · поле ${trip}`}
function spawnMedalRespawnTarget(){for(let attempt=0;attempt<8;attempt++){const fresh=generateField(`${baseSeed}:respawn:${fieldZone}:${trip}:${respawnSerial++}:${attempt}`,1);applyZoneProfile(fresh,fieldZone,rng);const t=fresh[0];if(targets.some(existing=>existing.alive&&d2(existing,t)<90*90))continue;t.id=targets.reduce((m,x)=>Math.max(m,x.id),0)+1;targets.push(t);return true}return false}
function masteredRespawnDelay(){return hasClearMedal(midgame.economyV2,fieldZone)?550:900}
function maybeRespawnMasteredZone(now:number){if(!zoneMastered(midgame,fieldZone)||cart>=capacity()-.01)return;const alive=targets.filter(t=>t.alive).length;if(alive>=fieldInitialTargetCount)return;const delay=masteredRespawnDelay();if(nextRespawnAt<=0)nextRespawnAt=now+delay;if(now<nextRespawnAt)return;const deficit=fieldInitialTargetCount-alive,spawnCount=hasClearMedal(midgame.economyV2,fieldZone)?Math.min(2,deficit):1;let made=0;for(let i=0;i<spawnCount;i++)if(spawnMedalRespawnTarget())made++;nextRespawnAt=now+(made?delay:Math.max(250,delay/2))}
function afterTargetBreak(){const alive=targets.filter(t=>t.alive).length;if(alive===0&&telemetry.destroyed>=fieldInitialTargetCount&&zoneMastered(midgame,fieldZone)&&awardClearMedal(midgame.economyV2,fieldZone)){showToast(`🏅 ${ZONE_DEFS[fieldZone].name}: полный сбор! Радиус шире, лом возвращается быстрее.`);saveGame()}if(zoneMastered(midgame,fieldZone))nextRespawnAt=performance.now()+masteredRespawnDelay()}
function resetExcursionMetrics(){telemetry={start:performance.now(),destroyed:0,pickupVisuals:0,components:0};comboCount=0;comboTimer=0}
function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);ctx.setTransform(d,0,0,d,0,0)}
new ResizeObserver(resize).observe(canvas);resize();
addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys.add(k);if(e.key.startsWith('Arrow'))e.preventDefault();if(k==='g'&&mode==='field'&&!talentScreen.hidden)closeTalents();else if(k==='g'&&mode==='field')garage()});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect();pointer={x:e.clientX-r.left+camera.x,y:e.clientY-r.top+camera.y};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!pointer)return;const r=canvas.getBoundingClientRect();pointer={x:e.clientX-r.left+camera.x,y:e.clientY-r.top+camera.y}});canvas.addEventListener('pointerup',e=>{pointer=null;canvas.releasePointerCapture(e.pointerId)});canvas.addEventListener('contextmenu',e=>e.preventDefault());

function move(dt:number){let x=0,y=0;if(keys.has('w')||keys.has('arrowup'))y--;if(keys.has('s')||keys.has('arrowdown'))y++;if(keys.has('a')||keys.has('arrowleft'))x--;if(keys.has('d')||keys.has('arrowright'))x++;if(!x&&!y&&pointer){x=pointer.x-player.x;y=pointer.y-player.y;if(Math.hypot(x,y)<14)x=y=0}const l=Math.hypot(x,y);if(!l)return;x/=l;y/=l;player.fx=x;player.fy=y;const e=effects(),comboMove=e.comboUnlocked&&comboCount>=5?e.comboMoveBonus:0,slow=1-.12*(cart/capacity()),speed=player.speed*e.moveMultiplier*(1+comboMove)*slow;player.x=clamp(player.x+x*speed*dt,35,WORLD.width-35);player.y=clamp(player.y+y*speed*dt,35,WORLD.height-35)}
function masteredFieldBonus(){const mastered=zoneMastered(midgame,fieldZone),medal=mastered&&hasClearMedal(midgame.economyV2,fieldZone);return{mastered,medal,radius:mastered?(medal?80:50):0,extra:mastered?(medal?2:1):0}}
function nearest(){if(cart>=capacity()-.01)return null;const bonus=masteredFieldBonus();let best:SalvageTarget|null=null,bd=Infinity;for(const t of targets){if(!t.alive)continue;const max=102+bonus.radius+getTargetClass(t.classId).radius,dd=d2(player,t);if(dd<max*max&&dd<bd){best=t;bd=dd}}return best}
function secondaryTargets(primary:SalvageTarget){const e=effects(),bonus=masteredFieldBonus(),count=(e.wideSwingUnlocked?1:0)+bonus.extra;if(count<=0)return[];const candidates=targets.filter(t=>t.alive&&t!==primary).map(t=>({t,dd:d2(player,t),max:118+bonus.radius+getTargetClass(t.classId).radius})).filter(x=>x.dd<x.max*x.max).sort((a,b)=>a.dd-b.dd);return candidates.slice(0,count).map(x=>x.t)}
function spawnResource(kind:ResourceKind,amount:number,count:number,t:Vec2){if(amount<=.005)return;for(let i=0;i<count;i++){const a=rng()*Math.PI*2,s=80+rng()*175;drops.push({kind,amount:amount/count,x:t.x,y:t.y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,age:0});telemetry.pickupVisuals++}}
function spawnSparks(t:Vec2,color:string,count:number,big=false){for(let i=0;i<count;i++){const a=rng()*Math.PI*2,s=(big?130:70)+rng()*(big?220:120),life=.24+rng()*.45;sparks.push({x:t.x,y:t.y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life,max:life,color,size:(big?2.5:1.5)+rng()*3})}}
function applyPity(t:SalvageTarget,component:ComponentKind|undefined){if(component)return component;const bearings=storedComps.bearing+comps.bearing,hydraulics=storedComps.hydraulic+comps.hydraulic;if(t.classId==='bike_fan'&&bearings<2&&totalDestroyed>=(bearings===0?8:17))return'bearing';if((t.classId==='medium_appliance'||t.classId==='large_appliance')&&hydraulics<1&&totalDestroyed>=22)return'hydraulic';if(!['small_scrap','cable'].includes(t.classId)&&effects().componentChanceBonus&&rng()<effects().componentChanceBonus)return rng()<.55?'bearing':rng()<.78?'motor':'electronics';return component}
function registerCombo(){const e=effects();if(!e.comboUnlocked)return;comboCount=comboTimer>0?Math.min(e.comboCap,comboCount+1):1;comboTimer=e.comboTimeout}
function breakTarget(t:SalvageTarget){
  t.alive=false;t.hp=0;telemetry.destroyed++;totalDestroyed++;registerCombo();
  const def=getTargetClass(t.classId),r=rollDrops(t.classId,rng),ym=zoneYieldMultiplier(midgame.currentZone);
  (['metal','copper','plastic'] as ResourceKind[]).forEach(k=>r.resources[k]*=ym);
  r.component=applyPity(t,r.component);
  const portSignature=midgame.currentZone==='z8'&&rollPortPowerAssembly(packE,t.classId,rng);
  const mastery=addActiveMastery(midgame,midgame.currentZone,masteryUnitsForTarget(t.classId));
  if(midgame.currentZone==='z8'){
    const capped=capZ8MasteryUntilSignature(mastery.after,packE.portPowerDiscovered);
    if(capped<mastery.after){midgame.mastery.z8=capped;mastery.after=capped;mastery.masteredNow=false}
  }
  if(mastery.masteredNow)showToast(`${ZONE_DEFS[midgame.currentZone].name} освоена! Можно назначать рабочего.`);
  const total=r.resources.metal+r.resources.copper+r.resources.plastic;let left=def.fragments;
  shake=Math.min(12,4+def.radius*.12);spawnSparks(t,'#ffd36d',Math.round(8+def.fragments*.75),def.radius>31);
  (['metal','copper','plastic'] as ResourceKind[]).forEach((k,i)=>{const remaining=2-i,n=i===2?left:Math.max(1,Math.min(left-remaining,Math.round(def.fragments*r.resources[k]/Math.max(.001,total))));left-=n;spawnResource(k,r.resources[k],n,t);if(r.resources[k]>.03)texts.push({x:t.x+(rng()-.5)*34,y:t.y-24-i*18,text:`+${r.resources[k].toFixed(r.resources[k]<10?1:0)} ${resourceName[k].toLowerCase()}`,color:resourceColor[k],life:1.15})});
  gainXp(xpForTarget(t.classId)*zoneXpMultiplier(midgame.currentZone),t);
  if(r.component){discoverComponent(midgame,r.component);comps[r.component]++;telemetry.components++;gainXp(xpForComponent());texts.push({x:t.x,y:t.y-76,text:`${componentIcon[r.component]} ${componentName[r.component]}!`,color:'#ffe56f',life:2,big:true});rareEl.innerHTML=`<small>${r.component==='motor'||r.component==='hydraulic'?'РЕДКИЙ КОМПОНЕНТ':'КОМПОНЕНТ'}</small><b>${componentIcon[r.component]} ${componentName[r.component]}</b><em>Сохрани — пригодится для станков, апгрейдов и контрактов</em>`;rareEl.className=`rare show ${r.component==='motor'||r.component==='hydraulic'?'strong':''}`;rareUntil=2.3;spawnSparks(t,'#78d8ff',20,true)}
  const mid=rollMidComponent(midgame,midgame.currentZone,t.classId,rng);
  if(mid){midHaul[mid]++;gainXp(4,t);texts.push({x:t.x,y:t.y-104,text:`◆ ${midComponentName(mid)}!`,color:'#8fe8ff',life:2.2,big:true});rareEl.innerHTML=`<small>НОВЫЙ КОМПОНЕНТ</small><b>◆ ${midComponentName(mid)}</b><em>${mid==='pump'?'Нужен для гидравлических модулей':'Редкий источник — крупная техника Зоны 3'}</em>`;rareEl.className='rare show strong';rareUntil=2.5;spawnSparks(t,'#63dfff',26,true)}
  if(midgame.currentZone==='z4'){
    const alu=z4AluminiumYield(t.classId,rng),take=Math.min(Math.max(0,capacity()-cart),alu);
    if(take>0){aluminiumHaul+=take;cart+=take;texts.push({x:t.x+22,y:t.y-92,text:`+${take.toFixed(1)} алюминий`,color:'#d7dbe0',life:1.5})}
    const industrial=rollIndustrialComponent(packB,t.classId,rng);
    if(industrial){industrialHaul[industrial]++;gainXp(6,t);texts.push({x:t.x,y:t.y-124,text:`◆ ${industrialName(industrial)}!`,color:'#ffd18b',life:2.4,big:true});rareEl.innerHTML=`<small>ПРОМЫШЛЕННЫЙ КОМПОНЕНТ</small><b>◆ ${industrialName(industrial)}</b><em>Нужен для модулей Hangar / Truck</em>`;rareEl.className='rare show strong industrialRare';rareUntil=2.7;spawnSparks(t,'#ffc45d',30,true)}
  }
  if(midgame.currentZone==='z5'||midgame.currentZone==='z6'){
    const packZone=midgame.currentZone as PackCZoneId,alloy=alloyYield(packZone,t.classId,rng),take=Math.min(Math.max(0,capacity()-cart),alloy);
    if(take>0){alloyHaul+=take;cart+=take;texts.push({x:t.x+25,y:t.y-96,text:`+${take.toFixed(1)} сплав`,color:'#86d7df',life:1.5})}
    const industrial=rollPackCComponent(packC,packZone,t.classId,rng);
    if(industrial){packCIndustrialHaul[industrial]++;gainXp(8,t);texts.push({x:t.x,y:t.y-132,text:`◆ ${packCComponentName(industrial)}!`,color:'#8ee8f0',life:2.5,big:true});rareEl.innerHTML=`<small>ТЯЖЁЛЫЙ КОМПОНЕНТ</small><b>◆ ${packCComponentName(industrial)}</b><em>Активное открытие промышленной цепочки Pack C</em>`;rareEl.className='rare show strong industrialRare packC';rareUntil=2.9;spawnSparks(t,'#70d9e5',34,true)}
  }
  if(midgame.currentZone==='z7'){
    const alloy=z7AlloyYield(t.classId,rng),take=Math.min(Math.max(0,capacity()-cart),alloy);
    if(take>0){alloyHaul+=take;cart+=take;texts.push({x:t.x+25,y:t.y-96,text:`+${take.toFixed(1)} тяжёлый сплав`,color:'#e2b477',life:1.5})}
    if(rollRecoveryAssembly(packD,t.classId,rng)){gainXp(12,t);texts.push({x:t.x,y:t.y-136,text:'◆ Recovery Assembly!',color:'#ffd08a',life:2.8,big:true});rareEl.innerHTML='<small>ТЯЖЁЛОЕ ВОССТАНОВЛЕНИЕ</small><b>◆ Recovery Assembly</b><em>Ключевая сборка для Recovery Rig</em>';rareEl.className='rare show strong industrialRare packD';rareUntil=3.1;spawnSparks(t,'#e4a55e',38,true)}
  }
  if(midgame.currentZone==='z8'){
    const advanced=z8AdvancedMetalYield(t.classId,rng);
    const takeAl=Math.min(Math.max(0,capacity()-cart),advanced.aluminiumScrap);
    if(takeAl>0){aluminiumHaul+=takeAl;cart+=takeAl;texts.push({x:t.x+24,y:t.y-96,text:`+${takeAl.toFixed(1)} портовый Al`,color:'#b8e2e6',life:1.5})}
    const takeAlloy=Math.min(Math.max(0,capacity()-cart),advanced.alloyScrap);
    if(takeAlloy>0){alloyHaul+=takeAlloy;cart+=takeAlloy;texts.push({x:t.x+28,y:t.y-114,text:`+${takeAlloy.toFixed(1)} портовый сплав`,color:'#79dce5',life:1.6})}
    const industrial=rollZ8IndustrialComponent(packC.discoveredIndustrial,t.classId,rng);
    if(industrial){packCIndustrialHaul[industrial]++;gainXp(10,t);texts.push({x:t.x,y:t.y-138,text:`◆ ${packCComponentName(industrial)}!`,color:'#8ee8f0',life:2.3,big:true})}
    if(portSignature){gainXp(15,t);texts.push({x:t.x,y:t.y-158,text:'◆ Port Power Assembly!',color:'#9ef4ff',life:3,big:true});rareEl.innerHTML='<small>ПОРТОВАЯ СИЛОВАЯ СБОРКА</small><b>◆ Port Power Assembly</b><em>Личная находка: ключ к Processing Plant</em>';rareEl.className='rare show strong industrialRare packE';rareUntil=3.3;spawnSparks(t,'#71e5ef',42,true)}
  }
  afterTargetBreak();
}
function combat(dt:number){selected=nearest();if(!selected)return;const before=selected.hp,e=effects(),comboMult=e.comboUnlocked?1+e.comboSpeedPerStack*Math.max(0,comboCount-1):1,tool=toolPowerMultiplier(equipmentLevels.tool),dps=BASE_DPS*e.dpsMultiplier*tool*comboMult,extras=secondaryTargets(selected);selected.hp-=dps*dt;extras.forEach((target,index)=>{const power=index===0&&e.wideSwingUnlocked ? .55 : index===0 ? .42 : index===1 ? .32 : .25;target.hp-=dps*power*dt});if(Math.floor(before/30)!==Math.floor(selected.hp/30))spawnSparks(selected,'#f2cf7b',2);for(const target of extras)if(target.alive&&target.hp<=0)breakTarget(target);if(selected.hp<=0){breakTarget(selected);selected=null}}

