function renderPackDPanels(){
  if(!packC.salvageYardOwned)return;const inv=currentPackDInventory(),gate=zoneGate('z7'),rigReady=canAcquireRecoveryRig(packD,inv,gate.ok),workshopReady=canAcquireIndustrialWorkshop(packD,inv,zoneMastered(midgame,'z7'));
  $('transportPanel').innerHTML+=`<div class="milestoneCard packDCard ${packD.recoveryRig.owned?'done':''}"><span class="packDTag">PACK D</span><h3>${packD.recoveryRig.owned?'✓ Recovery Rig':'🏗️ Recovery Rig'}</h3><p>Z7 signature assemblies: <b>${packD.recoveryAssemblies}</b> · capacity ${RECOVERY_RIG_CAPACITY_KG} кг.</p>${packD.recoveryRig.owned?`<div class="workerStatus">Rig: ${recoveryRigWeight(packD).toFixed(0)} / ${RECOVERY_RIG_CAPACITY_KG} кг · Truck теперь остаётся инфраструктурой старых маршрутов.</div>`:`<p>${money(RECOVERY_RIG_CASH)} · ${RECOVERY_RIG_RECIPE.metal} metal · ${RECOVERY_RIG_RECIPE.alloyBillet} усиленный сплав · Drive ${RECOVERY_RIG_RECIPE.drive} · Control ${RECOVERY_RIG_RECIPE.control} · Recovery Assembly ${RECOVERY_RIG_RECIPE.recoveryAssemblies}</p><button id="acquireRecoveryRig" ${rigReady?'':'disabled'}>${gate.ok?'Собрать Recovery Rig':'Сначала открыть Z7'}</button>`}</div>`;
  if(packD.recoveryRig.owned)$('transportPanel').innerHTML+=`<div class="milestoneCard packDCard ${packD.industrialWorkshopOwned?'done':''}"><h3>${packD.industrialWorkshopOwned?'✓ Industrial Workshop':'🏭 Industrial Workshop'}</h3><p>${packD.industrialWorkshopOwned?`Производственных ячеек: ${packD.productionCells}. Общих слотов мастерской: ${workshopSlots()}.`:`Тяжёлая база после полного освоения Z7 · ${money(INDUSTRIAL_WORKSHOP_CASH)} · ${INDUSTRIAL_WORKSHOP_RECIPE.granulate} гранулят · ${INDUSTRIAL_WORKSHOP_RECIPE.steelBlank} конструкц. профиль · ${INDUSTRIAL_WORKSHOP_RECIPE.alloyBillet} усиленный сплав · Heavy Frame ${INDUSTRIAL_WORKSHOP_RECIPE.heavyFrame}.`}</p>${packD.industrialWorkshopOwned?'':`<button id="acquireIndustrialWorkshop" ${workshopReady?'':'disabled'}>Развернуть Industrial Workshop</button>`}</div>`;
  if(packD.industrialWorkshopOwned){const hireReady=canHireFourthWorker(packD,cash);$('workerPanel').innerHTML+=`<div class="milestoneCard packDCard ${packD.crew4.hired?'done':''}"><h3>${packD.crew4.hired?'👷 Рабочий №4':'👷 Четвёртый рабочий'}</h3>${!packD.crew4.hired?`<p>${money(FOURTH_WORKER_COST)} · слот Industrial Workshop.</p><button id="hireWorker4" ${hireReady?'':'disabled'}>Нанять</button>`:`<p>Роль: <b>${packD.crew4.role==='operator'?'Operator':packD.crew4.assignment?`Scavenger · ${ZONE_DEFS[packD.crew4.assignment].name}`:'Scavenger · без маршрута'}</b></p><div class="crewRole"><button id="assignOperator4" class="${packD.crew4.role==='operator'?'active':''}" ${effects().operatorUnlocked?'':'disabled'}>${effects().operatorUnlocked?'Operator ×0.85':'Нужен талант: Оператор'}</button>${(['z1','z2','z3','z4','z5','z6','z7','z8'] as ZoneId[]).map(id=>`<button data-worker4-zone="${id}" ${zoneMastered(midgame,id)?'':'disabled'}>${ZONE_DEFS[id].name}</button>`).join('')}</div>`}</div>`}
}

function doAcquireProcessingPlant(){const inv=currentPackEInventory();if(acquireProcessingPlant(packE,inv,processingPlantContext())){applyPackEInventory(inv);showToast('Processing Plant открыт: 2 промышленные линии');saveGame();renderGarage()}}
function doStartPlantAlloy(){const scrap={value:packC.materials.alloyScrap},now=Date.now();if(startPlantAlloy(packE,scrap,now)){packC.materials.alloyScrap=scrap.value;const job=[...packE.production].reverse().find(item=>item.startedAt===now)??packE.production.at(-1);if(job){const raw=job.endsAt-job.startedAt,mult=effects().industrialProductionMultiplier*operatorFactor('plant_lines');if(mult<1)job.endsAt=job.startedAt+raw*mult}const line=job?packE.production.indexOf(job)+1:packE.production.length,duration=job?Math.max(0,(job.endsAt-job.startedAt)/1000):PLANT_ALLOY_SECONDS;showToast(`Processing Plant: линия ${Math.max(1,line)} · ${fmtLong(duration)}`);saveGame();renderGarage()}}
function renderPackEPanels(){
  if(!packD.industrialWorkshopOwned)return;
  const inv=currentPackEInventory(),ctx=processingPlantContext(),ready=canAcquireProcessingPlant(packE,inv,ctx),z8Gate=zoneGate('z8');
  const signature=packE.portPowerDiscovered?'найдена':'не найдена';
  if(!packE.processingPlantOwned){
    $('transportPanel').innerHTML+=`<div class="milestoneCard packECard"><span class="packETag">PACK E</span><h3>⚓ Z8 · Портовый терминал</h3><div class="packEGrid"><span>Доступ <b>${z8Gate.ok?'открыт':z8Gate.reason}</b></span><span>Освоение <b>${midgame.mastery.z8.toFixed(1)}%</b></span><span class="portSignature">Port Power Assembly <b>${packE.portPowerAssemblies} · ${signature}</b></span><span>Команда <b>${ctx.staffingReady?'готова':'нужно 3+ сотрудника и «Начальник смены»'}</b></span></div><h3>🏭 Processing Plant</h3><p>Кульминация текущей производственной цепочки: ${money(PROCESSING_PLANT_CASH)} · Metal ${PROCESSING_PLANT_RECIPE.metal} · Clean Cu ${PROCESSING_PLANT_RECIPE.cleanCopper} · Granulate ${PROCESSING_PLANT_RECIPE.granulate} · Конструкц. профиль ${PROCESSING_PLANT_RECIPE.steelBlank} · Усиленный сплав ${PROCESSING_PLANT_RECIPE.alloyBillet} · Drive ${PROCESSING_PLANT_RECIPE.drive} · Control ${PROCESSING_PLANT_RECIPE.control} · Hydraulic ${PROCESSING_PLANT_RECIPE.hydraulicPower} · Heavy Frame ${PROCESSING_PLANT_RECIPE.heavyFrame} · Controller ${PROCESSING_PLANT_RECIPE.industrialController} · Cylinder ${PROCESSING_PLANT_RECIPE.heavyHydraulicCylinder} · Port Power ${PROCESSING_PLANT_RECIPE.portPowerAssemblies}.</p><button id="acquireProcessingPlant" ${ready?'':'disabled'}>${!ctx.z8Mastered?'Сначала освой Z8':!ctx.staffingReady?'Нужна зрелая команда':ready?'Развернуть Processing Plant':'Не хватает производственных ресурсов'}</button></div>`;
    return;
  }
  const now=Date.now(),jobs=packE.production,canStart=canStartPlantAlloy(packE,packC.materials.alloyScrap);
  $('transportPanel').innerHTML+=`<div class="milestoneCard packECard done"><span class="packETag">PACK E · PLANT ONLINE</span><h3>🏭 Processing Plant</h3><div class="packEGrid"><span>Structural storage <b>${PROCESSING_PLANT_STORAGE_KG.toLocaleString('ru-RU')} кг</b></span><span>Линии <b>${jobs.length} / ${packE.plantLines}</b></span><span>Сплав-сырьё <b>${packC.materials.alloyScrap.toFixed(1)} кг</b></span><span>Усиленный сплав <b>${packC.materials.alloyBillet.toFixed(1)} кг</b></span></div><div class="plantLines">${Array.from({length:packE.plantLines},(_,i)=>{const job=jobs[i];return job?`<div class="plantLine"><b>Линия ${i+1} · Усиленный сплав</b><span>${fmtLong(Math.max(0,(job.endsAt-now)/1000))}</span><i><em style="width:${plantProductionProgress(job,now)*100}%"></em></i><small>${PLANT_ALLOY_INPUT} scrap → ${PLANT_ALLOY_OUTPUT} billet</small></div>`:`<div class="plantLine empty"><b>Линия ${i+1}</b><span>Свободна</span><small>Готова к следующей партии</small></div>`}).join('')}</div><button id="startPlantAlloy" ${canStart?'':'disabled'}>${canStart?`Запустить Alloy · ${PLANT_ALLOY_INPUT} → ${PLANT_ALLOY_OUTPUT} · ${fmtLong(PLANT_ALLOY_SECONDS)}`:jobs.length>=packE.plantLines?'Все линии заняты':`Нужно ${PLANT_ALLOY_INPUT} Alloy Scrap`}</button><small>Plant-линии отдельны от гаражной очереди и Industrial Workshop: это крупный параллельный слой, а не замена старых станков.</small></div>`;
}

function renderGarage(){advanceWorkshop(Date.now(),false);const growth=garageGrowthStage(installed,midgame.van.owned,midgame.worker.hired),garageBox=document.querySelector<HTMLElement>('.garageBox');if(garageBox)garageBox.dataset.growth=growth;$('garageTip').innerHTML=`<span class="garageGrowthBadge">${GARAGE_GROWTH_LABEL[growth]}</span> · Инструмент и тележка качаются отдельно от талантов.`;$('cash').textContent=`Наличные: ${money(cash)}`;$('storage').innerHTML=(['metal','copper','plastic'] as ResourceKind[]).map(k=>`<span>${resourceName[k]} <b>${storage[k].toFixed(1)} кг</b></span>`).join('');$('processed').innerHTML=(Object.keys(processed) as ProcessKind[]).map(k=>`<span>${processedName[k]} <b>${processed[k].toFixed(1)} кг</b></span>`).join('');$('storageComponents').innerHTML=(Object.keys(storedComps) as ComponentKind[]).map(k=>`<span class="${storedComps[k]?'owned':''}">${componentIcon[k]} ${componentName[k]} <b>${storedComps[k]}</b></span>`).join('');renderMachineCards();renderInspector();renderEquipment();renderQueue();renderContract();renderMidgamePanels();renderPackBPanels();renderPackCPanels();renderPackDPanels();renderPackEPanels();const rawValue=(storage.metal*BASE_SALE.metal+storage.copper*BASE_SALE.copper*effects().copperSaleMultiplier+storage.plastic*BASE_SALE.plastic)*effects().saleMultiplier,processedValue=(processed.briquette*PROCESSED_SALE.briquette+processed.cleanCopper*PROCESSED_SALE.cleanCopper*effects().copperSaleMultiplier+processed.granulate*PROCESSED_SALE.granulate)*effects().saleMultiplier;$<HTMLButtonElement>('sellRaw').disabled=rawValue<1;$<HTMLButtonElement>('sellRaw').textContent=`Продать сырьё · до ${money(rawValue)}`;$<HTMLButtonElement>('sellProcessed').disabled=processedValue<1;$<HTMLButtonElement>('sellProcessed').textContent=`Продать переработанное · до ${money(processedValue)}`;nextBtn.textContent=`Ехать: ${ZONE_DEFS[midgame.currentZone].name}`;renderProgress();lastGarageRender=performance.now()}
function buySelected(){const def=MACHINE_DEFS[selectedMachine],price=(def.buyPrice??Infinity)*effects().shopPriceMultiplier;if(installed.has(selectedMachine)||jobForMachine(selectedMachine)||!machineUnlocked(def,context())||cash<price)return;cash-=price;installed.add(selectedMachine);machineLevels[selectedMachine]=1;showToast(`${def.name} куплен и установлен`);saveGame();renderGarage();updateGoal()}
function saleKeys(mode:'raw'|'processed'){return mode==='raw'?(['metal','copper','plastic'] as ResourceKind[]):(Object.keys(processed) as ProcessKind[])}
function saleOwned(mode:'raw'|'processed',key:string){return mode==='raw'?storage[key as ResourceKind]:processed[key as ProcessKind]}
function saleLabel(mode:'raw'|'processed',key:string){return mode==='raw'?resourceName[key as ResourceKind]:processedName[key as ProcessKind]}
function saleBasePrice(mode:'raw'|'processed',key:string){const base=mode==='raw'?BASE_SALE[key as ResourceKind]:PROCESSED_SALE[key as ProcessKind];return base*((key==='copper'||key==='cleanCopper')?effects().copperSaleMultiplier:1)}
function saleInput(kind:'range'|'number',key:string){return Array.from(saleRowsEl.querySelectorAll<HTMLInputElement>(kind==='range'?'[data-sale-range]':'[data-sale-number]')).find(input=>(kind==='range'?input.dataset.saleRange:input.dataset.saleNumber)===key)}
function renderSaleTotal(){if(!saleMode)return;let total=0;for(const key of saleKeys(saleMode)){const input=saleInput('number',key),owned=saleOwned(saleMode,key),qty=Math.max(0,Math.min(owned,Number(input?.value)||0));total+=qty*saleBasePrice(saleMode,key)*effects().saleMultiplier;const row=saleRowsEl.querySelector<HTMLElement>(`[data-sale-payout="${key}"]`);if(row)row.textContent=money(qty*saleBasePrice(saleMode,key)*effects().saleMultiplier)}saleTotalEl.textContent=money(total);$<HTMLButtonElement>('saleConfirm').disabled=total<1}
function openSaleModal(mode:'raw'|'processed'){saleMode=mode;saleTitleEl.textContent=mode==='raw'?'Продать сырьё':'Продать переработанное';$('saleLead').textContent='Выбери количество по каждому ресурсу. Ничего не продаётся автоматически; MAX заполняет только выбранную строку.';saleRowsEl.innerHTML=saleKeys(mode).map(key=>{const owned=saleOwned(mode,key),price=saleBasePrice(mode,key)*effects().saleMultiplier;return`<article class="saleRow"><div class="saleRowTop"><div><b>${saleLabel(mode,key)}</b><small>На складе ${owned.toFixed(1)} кг · ${money(price)} / кг</small></div><div class="saleRowValue"><strong data-sale-payout="${key}">0 ₽</strong><em>за выбранное</em></div></div><div class="saleControls"><input type="range" min="0" max="${Math.max(0,owned)}" step="0.1" value="0" data-sale-range="${key}" ${owned>.001?'':'disabled'}><input type="number" inputmode="decimal" min="0" max="${Math.max(0,owned)}" step="0.1" value="0" data-sale-number="${key}" ${owned>.001?'':'disabled'}><button type="button" data-sale-max="${key}" ${owned>.001?'':'disabled'}>MAX</button></div></article>`}).join('');saleModal.hidden=false;renderSaleTotal()}
function syncSalePicker(source:HTMLInputElement,key:string){if(!saleMode)return;const owned=saleOwned(saleMode,key),qty=Math.round(Math.max(0,Math.min(owned,Number(source.value)||0))*10)/10,range=saleInput('range',key),number=saleInput('number',key);if(range)range.value=String(qty);if(number)number.value=String(qty);renderSaleTotal()}
function setSaleMax(key:string){if(!saleMode)return;const number=saleInput('number',key);if(!number)return;number.value=String(Math.round(saleOwned(saleMode,key)*10)/10);syncSalePicker(number,key)}
function commitPartialSale(){if(!saleMode)return;let value=0,sold=0;for(const key of saleKeys(saleMode)){const owned=saleOwned(saleMode,key),qty=Math.round(Math.max(0,Math.min(owned,Number(saleInput('number',key)?.value)||0))*10)/10;if(qty<=0)continue;value+=qty*saleBasePrice(saleMode,key)*effects().saleMultiplier;sold+=qty;if(saleMode==='raw')storage[key as ResourceKind]=Math.max(0,storage[key as ResourceKind]-qty);else processed[key as ProcessKind]=Math.max(0,processed[key as ProcessKind]-qty)}if(value<1)return;cash+=value;const label=saleMode==='raw'?'сырья':'переработанного';saleModal.hidden=true;saleMode=null;showToast(`Продано ${sold.toFixed(1)} кг ${label} на ${money(value)}`);saveGame();renderGarage()}
function sellAllFromModal(){if(!saleMode)return;const mode=saleMode;saleModal.hidden=true;saleMode=null;if(mode==='raw')sellRaw();else sellProcessed()}
function sellRaw(){const value=(storage.metal*BASE_SALE.metal+storage.copper*BASE_SALE.copper*effects().copperSaleMultiplier+storage.plastic*BASE_SALE.plastic)*effects().saleMultiplier;if(value<1)return;cash+=value;storage={metal:0,copper:0,plastic:0};showToast(`Продано на ${money(value)}`);saveGame();renderGarage()}
function sellProcessed(){const value=(processed.briquette*PROCESSED_SALE.briquette+processed.cleanCopper*PROCESSED_SALE.cleanCopper*effects().copperSaleMultiplier+processed.granulate*PROCESSED_SALE.granulate)*effects().saleMultiplier;if(value<1)return;cash+=value;processed={briquette:0,cleanCopper:0,granulate:0};showToast(`Переработанное продано на ${money(value)}`);saveGame();renderGarage()}
function settleQueueMutation(){removeTerminalWorkshopActions(workshop);advanceWorkshop(Date.now(),false);syncJobsView();saveGame();renderGarage()}
function removeQueuedAction(id:string){const result=cancelWorkshopAction(workshop,id,false);if(result.ok)settleQueueMutation()}
function requestCurrentQueueCancel(id:string){const action=workshop.actions.find(item=>item.id===id);if(!action)return;const result=cancelWorkshopAction(workshop,id,false);if(!result.needsConfirmation){if(result.ok)settleQueueMutation();return}pendingQueueCancelId=id;queueCancelText.textContent=isQueueBatch(action)?`«${action.label}»: готово ${action.completedCount} из ${action.requestedCount}. Готовые стаки останутся, текущий незавершённый стек и остаток batch будут отменены.`:`«${action.label}»: текущий прогресс будет обнулён. Уже списанные при старте ресурсы не возвращаются.`;queueCancelModal.hidden=false}
function confirmCurrentQueueCancel(){if(!pendingQueueCancelId){queueCancelModal.hidden=true;return}const id=pendingQueueCancelId;pendingQueueCancelId=null;queueCancelModal.hidden=true;const result=cancelWorkshopAction(workshop,id,true);if(result.ok)settleQueueMutation()}
function syncProcessBatchPicker(source:HTMLInputElement){const range=$<HTMLInputElement>('processBatchRange'),number=$<HTMLInputElement>('processBatchNumber');if(!range||!number)return;const count=clampBatchCount(Number(source.value));range.value=String(count);number.value=String(count);$('processBatchValue').textContent=String(count);const spec=processSpec(selectedMachine,machineLevels[selectedMachine]??1,effects().workshopYieldMultiplier);if(!spec)return;const duration=adjustedDuration(spec.durationSec),affordable=Math.max(0,Math.floor((storage[spec.resource]+1e-9)/spec.input));$('processBatchPlan').textContent=`План: ${count} × ${spec.input.toFixed(1)} кг → ${(count*spec.output).toFixed(1)} кг · ${fmtLong(duration*count)}. На складе сейчас хватает на ${affordable}; нехватка позже блокирует batch, не удаляя готовое.`;const button=$<HTMLButtonElement>('processMachine');button.textContent=`Добавить в очередь ×${count} · ${fmtLong(duration*count)}`}
function queueInputFor(kind:'range'|'number',encoded:string){return Array.from(queuePanelEl.querySelectorAll<HTMLInputElement>(kind==='range'?'[data-queue-batch-range]':'[data-queue-batch-number]')).find(input=>(kind==='range'?input.dataset.queueBatchRange:input.dataset.queueBatchNumber)===encoded)}
function syncWaitingBatchPicker(source:HTMLInputElement,encoded:string){const range=queueInputFor('range',encoded),number=queueInputFor('number',encoded);if(!range||!number)return;const min=Number(number.min)||1,count=Math.max(min,clampBatchCount(Number(source.value)));range.value=String(Math.min(Number(range.max)||100,count));number.value=String(count);const id=decodeURIComponent(encoded),action=workshop.actions.find(item=>item.id===id);if(action&&isQueueBatch(action)){const label=queuePanelEl.querySelector<HTMLElement>(`[data-queue-count="${encoded}"]`);if(label)label.textContent=`${action.completedCount} / ${count} стаков · осталось ${Math.max(0,count-action.completedCount)}`}}
function commitWaitingBatchPicker(source:HTMLInputElement,encoded:string){const id=decodeURIComponent(encoded),min=Number(source.min)||1,count=Math.max(min,clampBatchCount(Number(source.value)));if(setWaitingBatchCount(workshop,id,count))settleQueueMutation()}

function completeContract(contractId?:string){const ctx=contractContext(),offers=boardContractOffers(contractState,ctx,effects().contractChoices),def=(contractId?offers.find(x=>x.id===contractId):undefined)??activeBoardContract(contractState,ctx),needMult=contractNeedMultiplier(),needs=def.needs.map(n=>({...n,amount:isDiscreteContractNeed(n)?n.amount:n.amount*needMult}));if(!needs.every(n=>contractOwned(n)+1e-9>=n.amount))return;for(const n of needs)consumeContractNeed(n,n.amount);const rewardMult=contractScale(contractState,effects().urgentContracts),reward=def.cashReward*rewardMult,xpReward=Math.round(def.xpReward*rewardMult);cash+=reward;advanceBoardContract(contractState,def);gainXp(xpReward);showToast(`Контракт закрыт: +${money(reward)}, +${xpReward} XP`);saveGame();renderGarage()}
function standingOwned(buyer:StandingBuyerV3){return buyer.kind==='resource'?storage[buyer.key as ResourceKind]:processed[buyer.key as ProcessKind]}
function getContractV3View(){const ctx=contractContext(),standing=standingBuyersForContext(ctx).map(buyer=>({buyer,owned:standingOwned(buyer)})),specials=specialOrdersV3(contractState,ctx,effects().contractChoices).map(def=>({def,needs:def.needs.map(need=>({...need,owned:contractOwned(need)})),ready:def.needs.every(need=>contractOwned(need)+1e-9>=need.amount),reward:def.cashReward*Math.max(1.25,contractScale(contractState,effects().urgentContracts))}));return{standing,specials}}
function submitStandingV3(buyerId:string,requested:number){const buyer=standingBuyersForContext(contractContext()).find(item=>item.id===buyerId);if(!buyer)return null;const owned=standingOwned(buyer),result=deliverStandingV3(contractState,buyerId,owned,requested,effects().saleMultiplier);if(!result||result.consumed<=0)return result;if(buyer.kind==='resource')storage[buyer.key as ResourceKind]-=result.consumed;else processed[buyer.key as ProcessKind]-=result.consumed;cash+=result.cash;if(result.xp)gainXp(result.xp);showToast(`${buyer.name}: +${money(result.cash)}`);saveGame();renderGarage();return result}
function submitSpecialV3(contractId:string){const def=specialOrdersV3(contractState,contractContext(),effects().contractChoices).find(item=>item.id===contractId);if(!def||!def.needs.every(need=>contractOwned(need)+1e-9>=need.amount))return false;for(const need of def.needs)consumeContractNeed(need,need.amount);const rewardMult=Math.max(1.25,contractScale(contractState,effects().urgentContracts)),reward=def.cashReward*rewardMult,xpReward=Math.round(def.xpReward*rewardMult);cash+=reward;gainXp(xpReward);advanceSpecialOrderV3(contractState,def);showToast(`Спецзаказ: +${money(reward)}, +${xpReward} XP`);saveGame();renderGarage();return true}

function garage(){if(mode!=='field')return;const benchmark=recordActiveBenchmark(midgame.economyV2,fieldZone,{durationMs:performance.now()-telemetry.start,destroyed:telemetry.destroyed,resources:{metal:haul.metal+midgame.van.resources.metal+packB.truck.resources.metal+packD.recoveryRig.resources.metal,copper:haul.copper+midgame.van.resources.copper+packB.truck.resources.copper+packD.recoveryRig.resources.copper,plastic:haul.plastic+midgame.van.resources.plastic+packB.truck.resources.plastic+packD.recoveryRig.resources.plastic},components:{bearing:comps.bearing+midgame.van.components.bearing,motor:comps.motor+midgame.van.components.motor,hydraulic:comps.hydraulic+midgame.van.components.hydraulic,electronics:comps.electronics+midgame.van.components.electronics},devGranted:sessionStorage.getItem('__salvage_dev_grant__')==='1'},Date.now());if(benchmark.newBest)showToast(`Новый benchmark: ${ZONE_DEFS[fieldZone].name}`);mode='garage';platform.setGameplayActive(false,'garage');for(const k of ['metal','copper','plastic'] as ResourceKind[]){storage[k]+=haul[k];haul[k]=0}for(const k of Object.keys(comps) as ComponentKind[]){storedComps[k]+=comps[k];comps[k]=0}for(const k of Object.keys(midHaul) as MidComponentKind[]){midgame.midComponents[k]+=midHaul[k];midHaul[k]=0}packB.materials.aluminiumScrap+=aluminiumHaul;aluminiumHaul=0;(Object.keys(industrialHaul) as IndustrialComponentKind[]).forEach(k=>{packB.industrial[k]+=industrialHaul[k];industrialHaul[k]=0});packC.materials.alloyScrap+=alloyHaul;alloyHaul=0;(Object.keys(packCIndustrialHaul) as HeavyIndustrialComponentKind[]).forEach(k=>{packC.industrial[k]+=packCIndustrialHaul[k];packCIndustrialHaul[k]=0});const vanKg=unloadVanToStorage(midgame.van,storage,storedComps,midgame.midComponents),truck=unloadTruck(packB,storage);packC.materials.alloyScrap+=unloadPackCTruckAlloy(packC);const rig=unloadRecoveryRig(packD,storage);packB.materials.aluminiumScrap+=rig.aluminiumScrap;packC.materials.alloyScrap+=rig.alloyScrap;cart=0;$('tripSummary').textContent=`Последняя вылазка: ${telemetry.destroyed} целей · ${fmt((performance.now()-telemetry.start)/1000)}${rig.weight?` · Rig ${rig.weight.toFixed(0)} кг`:truck.weight?` · truck ${truck.weight.toFixed(0)} кг`:vanKg?` · фургон ${vanKg.toFixed(0)} кг`:''}`;garageScreen.hidden=false;renderGarage();saveGame()}
function leaveGarage(){garageScreen.hidden=true;mode='field';if(fieldZone!==midgame.currentZone||targets.filter(t=>t.alive).length<12)refreshField();resetExcursionMetrics();hud();platform.setGameplayActive(true,'leave_garage')}
